export function compareScenarios(a,b){const differences=[];for(const parent of [0,1]){const old=a.totals?.[parent],next=b.totals?.[parent];differences.push({category:'Kwota brutto — osoba '+(parent+1),before:old?.gross??null,after:next?.gross??null,delta:old?.gross!=null&&next?.gross!=null?Math.round((next.gross-old.gross)*100)/100:null});differences.push({category:'Dni świadczeń — osoba '+(parent+1),before:old?.days??0,after:next?.days??0});}const periods=r=>r.periods.map(p=>p.title+': '+p.start+' — '+p.end).join('; ');differences.push({category:'Okresy',before:periods(a),after:periods(b)});const deadlines=r=>r.deadlines.map(d=>d.title+': '+d.start).join('; ');differences.push({category:'Terminy',before:deadlines(a),after:deadlines(b)});const docs=r=>(r.documentRegister||[]).map(d=>d.code+' → '+d.recipient).join('; ');differences.push({category:'Dokumenty',before:docs(a),after:docs(b)});differences.push({category:'Ocena warunków',before:a.formalDecision?.label||'Wcześniejszy zapis',after:b.formalDecision?.label||'Wcześniejszy zapis'});return {differences,historyChanged:false,legalVersionChanged:a.rulesVersion!==b.rulesVersion};}
